ALTER TABLE claim ADD COLUMN status VARCHAR(10) DEFAULT 'DRAFT' NOT NULL;
-- A claim's number: given when it is opened, the sheet's next (1, 2, ...), with no gaps and never
-- reused. A draft has none; voiding clears it. The sheet keeps the last number it gave.
ALTER TABLE sheet ADD COLUMN last_claim_number BIGINT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN number BIGINT;
-- A settled claim's due, fixed when it is settled: its amount at its person's grade's rate then.
-- None while not settled, or when the grade had no rate (then the due stays live).
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(19, 2);
