import { getJson, postJson } from '../../api/http';
import { counts, type Claim } from '../claims/api';
import { sheetKey } from '../sheet/api';

/** A grade's rate on the sheet: a percent as two-decimal text, in force from its from-date
 *  (yyyy-MM-dd; null applies from the beginning of time). A grade with no rate is not listed. */
export type Rate = { sheetId: string; grade: string; pct: string; from: string | null };
/** A blank `from` sets the rate that applies from the beginning of time. */
export type RateInput = { grade: string; pct: string; from: string };

const base = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/rates`;

export const ratesKey = (sheetId: string) => [...sheetKey(sheetId), 'rates'] as const;

/** The sheet's rates, by grade, then by from-date (none first). */
export function listRates(sheetId: string): Promise<Rate[]> {
  return getJson<Rate[]>(base(sheetId));
}

/** Set a grade's rate from a from-date, replacing the one with the same grade and from-date;
 *  refused (rejects) when the percent is missing, negative or has more than two decimals, or the
 *  from-date is not a date. */
export function setRate(sheetId: string, by: string, input: RateInput): Promise<Rate> {
  return postJson<Rate>(`${base(sheetId)}?by=${encodeURIComponent(by)}`, input);
}

/** The grade's rate in force on a date (yyyy-MM-dd): the one with the latest from-date on or
 *  before it; undefined (n/a) when the date is before every rate the grade has, or it has none. */
export function rateOn(rates: Rate[] | undefined, grade: string, date: string): string | undefined {
  let found: Rate | undefined;
  for (const r of rates ?? []) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (found === undefined || (found.from ?? '') < (r.from ?? '')) found = r;
  }
  return found?.pct;
}

/** The rate in force on a date for each grade that has one then. */
export function rateByGrade(rates: Rate[] | undefined, date: string): Map<string, string> {
  const byGrade = new Map<string, string>();
  for (const r of rates ?? []) {
    const pct = rateOn(rates, r.grade, date);
    if (pct !== undefined) byGrade.set(r.grade, pct);
  }
  return byGrade;
}

/** Two-decimal text as a whole number of hundredths. */
function hundredths(text: string): bigint {
  const [whole, frac = ''] = text.trim().split('.');
  return BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
}

/** An amount times a percent, divided by 100, rounded half to even to two decimals; null (n/a)
 *  when there is no rate. Exact: worked in whole hundredths. */
export function dueOf(amount: string, pct: string | undefined): string | null {
  if (pct === undefined) return null;
  // amount (1/100) x pct (1/100) / 100 is in 1/1_000_000; to cents is / 10_000, half to even.
  const product = hundredths(amount) * hundredths(pct);
  const floor = product / 10_000n;
  const rest = product % 10_000n;
  const cents = rest > 5_000n || (rest === 5_000n && floor % 2n === 1n) ? floor + 1n : floor;
  return formatCents(cents);
}

/** A claim's due: the one fixed when it was settled, else live at the grade's rate in force on the
 *  claim's date. */
export const claimDue = (c: Claim, rates: Rate[] | undefined, grade: string) =>
  c.settledDue ?? dueOf(c.amount, rateOn(rates, grade, c.date));

/** A person's due-total: the sum of their counting claims' due figures (n/a ones skipped); n/a
 *  when their grade has no rate today (`pct`) and none of those claims keeps a settled figure. */
export function personDue(claims: Claim[], rates: Rate[] | undefined, grade: string, pct: string | undefined) {
  const own = claims.filter(counts);
  if (pct === undefined && !own.some((c) => c.settledDue !== null)) return null;
  return sumDues(own.map((c) => claimDue(c, rates, grade)));
}

/** Add up two-decimal dues, skipping n/a. */
export function sumDues(dues: Array<string | null>): string {
  return formatCents(dues.reduce<bigint>((t, d) => (d === null ? t : t + hundredths(d)), 0n));
}

function formatCents(cents: bigint): string {
  const frac = (cents % 100n).toString().padStart(2, '0');
  return `${cents / 100n}.${frac}`;
}

/** A due as shown: n/a when there is none. */
export const showDue = (due: string | null) => due ?? 'n/a';
import { useQuery } from '@tanstack/react-query';
import { claimsKey, listClaims } from '../claims/api';
import { listPeople, peopleKey } from '../people/api';
import { useSheetToday } from '../sheet/api';
import { listRates, personDue, rateByGrade, ratesKey, sumDues } from './api';

/** The sheet's due-total: everyone's due-total added up, skipping those shown n/a. */
export function DueTotal({ sheetId, user }: { sheetId: string; user: string }) {
  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
  const claims = useQuery({ queryKey: claimsKey(sheetId), queryFn: () => listClaims(sheetId) });
  const rates = useQuery({ queryKey: ratesKey(sheetId), queryFn: () => listRates(sheetId) });
  const byGrade = rateByGrade(rates.data, useSheetToday(sheetId, user));
  const dues = (people.data ?? []).map((p) =>
    personDue((claims.data ?? []).filter((c) => c.personId === p.id), rates.data, p.grade, byGrade.get(p.grade)),
  );
  return (
    <p>
      Due total <span data-testid="rollup-due-total">{sumDues(dues)}</span>
    </p>
  );
}
import { getJson, postJson, putJson } from '../../api/http';
import { sheetKey } from '../sheet/api';

/** A claim's status: DRAFT, opened to OPEN, settled to SETTLED; a DRAFT or OPEN claim can be voided. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';
/** A change of a claim's status. */
export type ClaimAction = 'open' | 'settle' | 'void';

/** A claim: its amount as two-decimal text, its date (yyyy-MM-dd), its note, its status and its
 *  number on the sheet (given when opened; null while a draft or once voided), and its settled due
 *  (fixed when settled; null otherwise, or when there was no rate then — its due stays live), and who
 *  opened it (null while a draft; that user cannot settle it). */
export type Claim = {
  id: number; sheetId: string; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
  number: number | null; settledDue: string | null; openedBy: string | null;
};
export type ClaimInput = { amount: string; date: string; note: string };

const sheetBase = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}`;

export const claimsKey = (sheetId: string) => [...sheetKey(sheetId), 'claims'] as const;

/** Every claim on the sheet, newest first. */
export function listClaims(sheetId: string): Promise<Claim[]> {
  return getJson<Claim[]>(`${sheetBase(sheetId)}/claims`);
}

/** Add a claim to a person; refused (rejects) when the amount is missing, negative or has more
 *  than two decimals, or the date is not a date. A blank date takes the sheet's today. */
export function addClaim(sheetId: string, by: string, personId: number, input: ClaimInput): Promise<Claim> {
  return postJson<Claim>(`${sheetBase(sheetId)}/people/${personId}/claims?by=${encodeURIComponent(by)}`, input);
}

/** Edit a claim; refused (rejects) like an add. */
export function updateClaim(sheetId: string, by: string, id: number, input: ClaimInput): Promise<Claim> {
  return putJson<Claim>(`${sheetBase(sheetId)}/claims/${id}?by=${encodeURIComponent(by)}`, input);
}

/** Change a claim's status; refused (rejects) when its status does not allow the change, or when the
 *  user settling it is the one who opened it. */
export function moveClaim(sheetId: string, by: string, id: number, action: ClaimAction): Promise<Claim> {
  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/${action}?by=${encodeURIComponent(by)}`, {});
}

/** Whether a claim counts toward claimed, due-total and every total: only OPEN and SETTLED do. */
export const counts = (c: Claim) => c.status === 'OPEN' || c.status === 'SETTLED';

/** Sum the amounts of the claims that count (see `counts`) exactly (in cents), shown with two decimals. */
export function sumAmounts(claims: Claim[]): string {
  const cents = claims.filter(counts).reduce((t, c) => t + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useSubmitOnce } from '../../forms/useSubmitOnce';
import { claimDue, showDue, type Rate } from '../rates/api';
import { addClaim, claimsKey, moveClaim, updateClaim, type Claim, type ClaimAction, type ClaimInput } from './api';

const EMPTY: ClaimInput = { amount: '', date: '', note: '' };

/** A person's claims: a form that adds a claim or edits one, and the claims newest first, each
 *  with its status, its due (fixed when settled, else at the person's `grade`'s rate in force on the
 *  claim's date; none when there is no such rate)
 *  who opened it, and buttons that change its status (the user who opened a claim cannot settle it). */
export function PersonClaims({ sheetId, user, personId, claims, grade, rates }: {
  sheetId: string; user: string; personId: number; claims: Claim[]; grade: string; rates: Rate[] | undefined;
}) {
  const queryClient = useQueryClient();
  const [form, setForm] = useState<ClaimInput>(EMPTY);
  const [editing, setEditing] = useState<number | null>(null);

  const save = useMutation({
    mutationFn: (v: { id: number | null; input: ClaimInput }) =>
      v.id === null ? addClaim(sheetId, user, personId, v.input) : updateClaim(sheetId, user, v.id, v.input),
    onSuccess: () => {
      setForm(EMPTY);
      setEditing(null);
      return queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });

  const submitOnce = useSubmitOnce();
  const actOnce = useSubmitOnce();

  // The claim whose last status change was refused; cleared by the next action on any claim here.
  const move = useMutation({
    mutationFn: (v: { id: number; action: ClaimAction }) => moveClaim(sheetId, user, v.id, v.action),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
  });

  const act = (id: number, action: ClaimAction) => {
    actOnce(() => {
      move.reset();
      return move.mutateAsync({ id, action });
    });
  };

  const change = (patch: Partial<ClaimInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    save.reset();
  };

  const open = (c: Claim) => {
    setForm({ amount: c.amount, date: c.date, note: c.note });
    setEditing(c.id);
    save.reset();
    move.reset();
  };

  const cancel = () => {
    setForm(EMPTY);
    setEditing(null);
    save.reset();
  };

  return (
    <div>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          const v = { id: editing, input: form };
          submitOnce(() => {
            save.reset();
            return save.mutateAsync(v);
          });
        }}
      >
        <input data-testid="claim-form-amount" placeholder="Amount" value={form.amount}
          onChange={(e) => change({ amount: e.target.value })} />{' '}
        <input type="date" data-testid="claim-form-date" value={form.date}
          onChange={(e) => change({ date: e.target.value })} />{' '}
        <input data-testid="claim-form-note" placeholder="Note" value={form.note}
          onChange={(e) => change({ note: e.target.value })} />{' '}
        <button type="submit" data-testid="claim-form-submit" disabled={save.isPending}>
          {editing === null ? 'Add claim' : 'Save claim'}
        </button>
        {save.isError && (
          <span data-testid="claim-form-error">A claim needs an amount of 0.00 or more with up to two decimals.</span>
        )}
      </form>
      <table>
        <tbody>
          {claims.map((c) => (
            <tr key={c.id} data-testid={`claim-row-${c.id}`}>
              <td data-testid="claim-number">{c.number ?? ''}</td>
              <td data-testid="claim-amount">{Number(c.amount).toFixed(2)}</td>
              <td data-testid="claim-date">{c.date}</td>
              <td data-testid="claim-note">{c.note}</td>
              <td data-testid="claim-due">{showDue(claimDue(c, rates, grade))}</td>
              <td data-testid="claim-status">{c.status}</td>
              <td data-testid="claim-opened-by">{c.openedBy ?? ''}</td>
              <td>
                {(['open', 'settle', 'void'] as const).map((a) => (
                  <button key={a} type="button" data-testid={`claim-${a}`} disabled={move.isPending}
                    onClick={() => act(c.id, a)}>
                    {a === 'open' ? 'Open' : a === 'settle' ? 'Settle' : 'Void'}
                  </button>
                ))}{' '}
                <button type="button" data-testid="claim-edit" onClick={() => open(c)}>
                  Edit
                </button>
                {editing === c.id && (
                  <button type="button" data-testid="claim-cancel" onClick={cancel}>
                    Cancel
                  </button>
                )}
                {move.isError && move.variables?.id === c.id && (
                  <span data-testid="claim-error">{c.status === 'OPEN' && move.variables.action === 'settle'
                    ? 'The user who opened a claim cannot settle it.'
                    : `A ${c.status} claim cannot be ${move.variables.action === 'open'
                      ? 'opened' : move.variables.action === 'settle' ? 'settled' : 'voided'}.`}</span>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { HttpError } from '../../api/http';
import { useSubmitOnce } from '../../forms/useSubmitOnce';
import { PersonClaims } from '../claims/PersonClaims';
import { claimsKey, listClaims, sumAmounts } from '../claims/api';
import { listRates, personDue, rateByGrade, ratesKey, showDue } from '../rates/api';
import { useSheetToday } from '../sheet/api';
import { GRADES, addPerson, listPeople, peopleKey, updatePerson, type Person, type PersonInput } from './api';

const EMPTY: PersonInput = { name: '', grade: 'A' };

/** The people on the sheet: a form that adds a person or edits one, and the list in added order,
 *  each with their claimed total, their due-total (the sum of their claims' due figures; n/a
 *  when their grade has no rate on the sheet's today and no settled claim keeps a figure) and their claims. */
export function People({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
  const claims = useQuery({ queryKey: claimsKey(sheetId), queryFn: () => listClaims(sheetId) });
  const rates = useQuery({ queryKey: ratesKey(sheetId), queryFn: () => listRates(sheetId) });
  const byGrade = rateByGrade(rates.data, useSheetToday(sheetId, user));
  const [form, setForm] = useState<PersonInput>(EMPTY);
  // The person being edited and the version of them the form loaded.
  const [editing, setEditing] = useState<{ id: number; version: number } | null>(null);

  const save = useMutation({
    mutationFn: async (v: { editing: { id: number; version: number } | null; input: PersonInput }) => {
      if (v.editing === null) return addPerson(sheetId, user, v.input);
      try {
        return await updatePerson(sheetId, user, v.editing.id, v.editing.version, v.input);
      } catch (e) {
        // Someone else saved the person since the form loaded them: show what is stored now. The
        // form keeps the version it loaded, so a save goes through once the editor is opened again.
        if (e instanceof HttpError && e.status === 409) {
          const now = await queryClient.fetchQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId), staleTime: 0 });
          const current = now.find((p) => p.id === v.editing?.id);
          if (current) setForm({ name: current.name, grade: current.grade });
        }
        throw e;
      }
    },
    onSuccess: () => {
      setForm(EMPTY);
      setEditing(null);
      return queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
  });

  const submitOnce = useSubmitOnce();

  const change = (patch: Partial<PersonInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    save.reset();
  };

  const open = (p: Person) => {
    setForm({ name: p.name, grade: p.grade });
    setEditing({ id: p.id, version: p.version });
    save.reset();
  };

  const cancel = () => {
    setForm(EMPTY);
    setEditing(null);
    save.reset();
  };

  return (
    <section>
      <h3>People</h3>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          const v = { editing, input: form };
          submitOnce(() => {
            save.reset();
            return save.mutateAsync(v);
          });
        }}
      >
        <label>
          Name{' '}
          <input data-testid="person-form-name" value={form.name} onChange={(e) => change({ name: e.target.value })} />
        </label>{' '}
        <label>
          Grade{' '}
          <select data-testid="person-form-grade" value={form.grade} onChange={(e) => change({ grade: e.target.value })}>
            {GRADES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
          {editing === null ? 'Add person' : 'Save person'}
        </button>
        {editing !== null && (
          <button type="button" data-testid="person-form-cancel" onClick={cancel}>
            Cancel
          </button>
        )}
        {save.isError && (
          <span data-testid="person-form-error">
            {save.error instanceof HttpError && save.error.status === 409
              ? 'Someone else saved this person meanwhile: the form shows what is stored now. Open the editor again to edit it.'
              : 'A person needs a name not already in use.'}
          </span>
        )}
      </form>
      {people.isError && <p data-testid="people-error">The people could not be loaded.</p>}
      <table>
        <tbody>
          {(people.data ?? []).map((p) => {
            const own = (claims.data ?? []).filter((c) => c.personId === p.id);
            const claimed = sumAmounts(own);
            const pct = byGrade.get(p.grade);
            return (
              <tr key={p.id} data-testid={`person-row-${p.id}`}>
                <td data-testid="person-name">{p.name}</td>
                <td data-testid="person-grade">{p.grade}</td>
                <td>
                  Claimed <span data-testid="person-claimed">{claimed}</span>
                </td>
                <td>
                  Due <span data-testid="person-due-total">{showDue(personDue(own, rates.data, p.grade, pct))}</span>
                </td>
                <td>
                  <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => open(p)}>
                    Edit
                  </button>
                </td>
                <td>
                  <PersonClaims sheetId={sheetId} user={user} personId={p.id} claims={own} grade={p.grade} rates={rates.data} />
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </section>
  );
}
import { getJson, postJson, putJson } from '../../api/http';
import { sheetKey } from '../sheet/api';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

/** `version` is raised by every saved edit; an edit sends the version its form loaded. */
export type Person = { id: number; sheetId: string; name: string; grade: Grade; version: number };
export type PersonInput = { name: string; grade: string };

const base = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/people`;

export const peopleKey = (sheetId: string) => [...sheetKey(sheetId), 'people'] as const;

/** The sheet's people, in the order they were added. */
export function listPeople(sheetId: string): Promise<Person[]> {
  return getJson<Person[]>(base(sheetId));
}

/** Add a person; refused (rejects) when the name is empty or already in use on the sheet. */
export function addPerson(sheetId: string, by: string, input: PersonInput): Promise<Person> {
  return postJson<Person>(`${base(sheetId)}?by=${encodeURIComponent(by)}`, input);
}

/** Edit a person loaded at `version`; refused (rejects) like an add, and with a 409 when someone
 *  else has saved the person since. */
export function updatePerson(sheetId: string, by: string, id: number, version: number, input: PersonInput): Promise<Person> {
  return putJson<Person>(`${base(sheetId)}/${id}?by=${encodeURIComponent(by)}`, { ...input, version });
}
import { useQuery } from '@tanstack/react-query';
import { claimsKey, listClaims, sumAmounts } from './api';

/** The sheet's claimed-total: everyone's OPEN and SETTLED claims added up. */
export function ClaimedTotal({ sheetId }: { sheetId: string; user: string }) {
  const claims = useQuery({ queryKey: claimsKey(sheetId), queryFn: () => listClaims(sheetId) });
  return (
    <p>
      Claimed total <span data-testid="rollup-claimed-total">{sumAmounts(claims.data ?? [])}</span>
    </p>
  );
}
